private int startQueryTargetService(int i2, int i3, QvQueryServiceCallback qvQueryServiceCallback) {
    int iQueryServiceAddress = SDKVariates.getP2PManager().queryServiceAddress(i3, i2, qvQueryServiceCallback);
    LogUtil.i("startQueryTargetService group id: " + i2 + " ,type mask: " + i3 + " ,ret: " + iQueryServiceAddress);
    return iQueryServiceAddress;
}
